                if ($this->isNew()) {
                    $this->doInsert($con);
                } else {
                    $this->doUpdate($con);
                }
                $affectedRows += 1;
                $this->resetModified();
            }

            if ($this->metadatosExpedientesScheduledForDeletion !== null) {
                if (!$this->metadatosExpedientesScheduledForDeletion->isEmpty()) {
                    MetadatosExpedienteQuery::create()
                        ->filterByPrimaryKeys($this->metadatosExpedientesScheduledForDeletion->getPrimaryKeys(false))
                        ->delete($con);
                    $this->metadatosExpedientesScheduledForDeletion = null;
                }
            }

            if ($this->collMetadatosExpedientes !== null) {
                foreach ($this->collMetadatosExpedientes as $referrerFK) {
                    if (!$referrerFK->isDeleted() && ($referrerFK->isNew() || $referrerFK->isModified())) {
                        $affectedRows += $referrerFK->save($con);
                    }
                }
            }

            if ($this->metadatosSubseriesScheduledForDeletion !== null) {
                if (!$this->metadatosSubseriesScheduledForDeletion->isEmpty()) {
                    MetadatosSubserieQuery::create()
                        ->filterByPrimaryKeys($this->metadatosSubseriesScheduledForDeletion->getPrimaryKeys(false))
                        ->delete($con);
                    $this->metadatosSubseriesScheduledForDeletion = null;
                }
            }

            if ($this->collMetadatosSubseries !== null) {
                foreach ($this->collMetadatosSubseries as $referrerFK) {
                    if (!$referrerFK->isDeleted() && ($referrerFK->isNew() || $referrerFK->isModified())) {
                        $affectedRows += $referrerFK->save($con);
                    }
                }
            }

            if ($this->metadatosTipodocsScheduledForDeletion !== null) {
                if (!$this->metadatosTipodocsScheduledForDeletion->isEmpty()) {
                    MetadatosTipodocQuery::create()
                        ->filterByPrimaryKeys($this->metadatosTipodocsScheduledForDeletion->getPrimaryKeys(false))
                        ->delete($con);
