                }
            }

            if ($this->collMetadatosTipodocs !== null) {
                foreach ($this->collMetadatosTipodocs as $referrerFK) {
                    if (!$referrerFK->isDeleted() && ($referrerFK->isNew() || $referrerFK->isModified())) {
