    protected function doInsert(PropelPDO $con)
    {
        $this->modifiedColumns[] = MetaDatosPeer::METADATO_ID;
        $criteria = $this->buildCriteria();
        if ($criteria->keyContainsValue(MetaDatosPeer::METADATO_ID) ) {
